//! Actual v21 Java engine output from ModernQuestProtocolTest, not a Rust fixture encoder.
use super::*;
use crate::modern_lito::{application_protocol as app, npc_protocol as npc};
const BEFORE:&str="";
const WIN:&str="";
const LOSS:&str="";
fn bytes(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}
pub(crate) fn sample(which: &str) -> npc::Reply {
    let hex = match which {
        "before" => BEFORE,
        "win" => WIN,
        "loss" => LOSS,
        _ => panic!("unknown fixture"),
    };
    match app::decode_response_version(&bytes(hex), 21)
        .unwrap()
        .response
    {
        app::Response::Npc(r) => r,
        _ => panic!("wrong kind"),
    }
}
#[test]
fn actual_java_objective_before_win_and_hidden_opponent_loss_are_strictly_accepted() {
    let a = sample("before");
    let b = sample("win");
    let c = sample("loss");
    assert!(npc::follows(Some(&a), &b));
    let w = &b.frame.as_ref().unwrap().combat.world;
    let l = &c.frame.as_ref().unwrap().combat.world;
    assert_eq!(
        w.quest.as_ref().unwrap().actors[0].action(&w.quest.as_ref().unwrap().targets[0]),
        35
    );
    assert_eq!(
        w.completion.as_ref().unwrap().event,
        l.completion.as_ref().unwrap().event
    );
    assert_eq!(l.actors[0].entity_id, 2);
    assert_eq!(l.completion.as_ref().unwrap().event.participants.len(), 2);
    let q = l.quest.as_ref().unwrap();
    assert_eq!(q.winning_lane, Some(0));
    assert!(q.actors.is_empty());
    assert!(q.exchanges.is_empty());
    assert!(q.targets.iter().all(|t| t.lane() == 1));
    assert_eq!(b.echo.action, npc::Action::AttackObjective);
    assert!(b.echo.target().is_none());
    assert_eq!(b.echo.objective().unwrap().slot, 4);
    for hex in [BEFORE, WIN, LOSS] {
        assert!(app::decode_response_version(&bytes(hex), 20).is_err());
    }
}
#[test]
fn latest_confirmed_objective_receipt_wins_animation_without_aliasing_npc_or_player_ids() {
    let before = sample("before");
    let won = sample("win");
    let a = crate::modern_lito::npc_presentation::player_attack(before.frame.as_ref().unwrap(), 1)
        .unwrap();
    let b = crate::modern_lito::npc_presentation::player_attack(won.frame.as_ref().unwrap(), 1)
        .unwrap();
    assert!(b.revision > a.revision);
    assert_eq!(
        b.revision,
        won.frame
            .as_ref()
            .unwrap()
            .combat
            .world
            .quest
            .as_ref()
            .unwrap()
            .exchanges[0]
            .revision
    );
    assert_eq!(
        b.cell,
        Some(
            won.frame
                .as_ref()
                .unwrap()
                .combat
                .world
                .quest
                .as_ref()
                .unwrap()
                .targets[0]
                .cell
        )
    );
    assert!(
        crate::modern_lito::npc_presentation::player_attack(won.frame.as_ref().unwrap(), 2)
            .is_none()
    );
}
#[test]
fn actual_java_bytes_reject_every_truncation_and_appendix_reserved_count_corruption() {
    for hex in [BEFORE, WIN, LOSS] {
        let data = bytes(hex);
        for len in 0..data.len() {
            assert!(
                app::decode_response_version(&data[..len], 21).is_err(),
                "length {len}"
            );
        }
    }
    let reply = sample("before");
    let q = reply
        .frame
        .as_ref()
        .unwrap()
        .combat
        .world
        .quest
        .as_ref()
        .unwrap();
    let mut encoded = Vec::new();
    encode(&mut encoded, Some(q));
    assert_eq!(decode(&encoded).unwrap(), (Some(q.clone()), encoded.len()));
    for i in [0, 1, 2, 3, 4, 5, 6, 7, 24, 25, 31, 35, 38, 39, 41, 42, 43] {
        let mut invalid = encoded.clone();
        invalid[i] = 255;
        assert!(decode(&invalid).is_err(), "byte {i}");
    }
}
#[test]
fn missing_or_forged_death_wrong_classic_namespace_and_changed_plan_are_rejected() {
    let before = sample("before");
    let won = sample("win");
    for fault in 0..7 {
        let mut bad = won.clone();
        let f = bad.frame.as_mut().unwrap();
        let q = f.combat.world.quest.as_mut().unwrap();
        match fault {
            0 => q.exchanges.clear(),
            1 => q.winning_lane = Some(1),
            2 => q.actors[0].death_revision -= 1,
            3 => q.exchanges[0].entity_id = 2,
            4 => q.targets[0].max_hp = 0,
            5 => q.actors[0].hp = 1,
            _ => q.exchanges[0].outcome.applied_damage = i64::MAX,
        };
        assert!(bad.validate().is_err(), "fault {fault}");
        assert!(!npc::follows(Some(&before), &bad));
    }
    let mut changed = before.clone();
    changed
        .frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .quest
        .as_mut()
        .unwrap()
        .targets[0]
        .max_hp += 1;
    changed
        .frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .quest
        .as_mut()
        .unwrap()
        .actors[0]
        .hp += 1;
    changed.frame.as_mut().unwrap().combat.world.revision += 1;
    assert!(!npc::follows(Some(&before), &changed));
}
